const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const baseDir = "/mnt/windows/Users/adity/Documents/Aditya/Agents/n8n/ReelAgent";
const textFilePath = path.join(baseDir, "output", "current_text.txt");
const historyPath = path.join(baseDir, "output", "history.txt");

const ollamaText = $input.item.json.content || "";

try {
    // 1. SPLIT THE DATA: Find the barrier and chop the text in two
    const parts = ollamaText.split('===CAPTION===');
    if (parts.length < 2) {
        throw new Error("FATAL: AI failed to generate the CAPTION delimiter. Workflow killed.");
    }

    const videoText = parts[0].trim();
    const igCaption = parts[1].trim();

    // 2. Extract the Title for the Kill Switch
    const lines = videoText.split('\n').filter(line => line.trim() !== '');
    if (lines.length === 0) {
        throw new Error("AI returned an empty string for the video text.");
    }
    const newTitle = lines[0].trim();

    // 3. THE KILL SWITCH: Check for duplicates
    let history = "";
    if (fs.existsSync(historyPath)) {
        history = fs.readFileSync(historyPath, 'utf-8');
    }
    if (history.includes("- " + newTitle)) {
        throw new Error(`FATAL: The AI generated a duplicate title ("${newTitle}"). Workflow killed.`);
    }

    // 4. Write ONLY the video text for Python to render
    fs.writeFileSync(textFilePath, videoText, 'utf-8');

    // 5. Append the new Title to memory
    fs.appendFileSync(historyPath, "- " + newTitle + "\n", 'utf-8');

    // 6. Run the Python rendering script (UPDATED FOR LINUX)
    const command = `python3 "${path.join(baseDir, "generator.py")}"`;
    const stdout = execSync(command).toString();

    // 7. Pass the generated IG caption AND the title forward
    return [{ json: { status: "success", title: newTitle, caption: igCaption, file: "final_reel.mp4" } }];
} catch (error) {
    // THIS STOPS THE WORKFLOW DEAD IN ITS TRACKS
    throw new Error("Execution halted: " + error.message);
}

